INSERT INTO `ai_citations` VALUES (1,2,1,1,1,7,'Breathing and circulation notes',NULL,NULL,'Two circuits working together','This is how the two systems respond together to the body\'s needs.','2026-10-20 23:24:17'),(2,2,2,1,1,1,'Breathing and circulation notes',NULL,NULL,'Why your body needs both systems','The respiratory system brings oxygen into the body and removes carbon dioxide.','2026-10-20 23:24:17'),(3,2,3,1,1,8,'Breathing and circulation notes',NULL,NULL,'Keeping both systems healthy','Smoking damages the lining of the airways and the walls of the alveoli, and it makes the heart work harder.','2026-10-20 23:24:17'),(4,4,1,2,2,12,'Heredity notes',3,3,NULL,'Geneticists write the dominant allele with a capital letter and the recessive allele with the same letter in lowercase.','2026-10-20 23:24:18'),(5,4,2,2,2,11,'Heredity notes',2,2,NULL,'One allele can hide the effect of the other: the allele that shows is dominant and the hidden one is recessive.','2026-10-20 23:24:18'),(6,4,3,2,2,13,'Heredity notes',4,4,NULL,'Not every trait follows simple dominance.','2026-10-20 23:24:18'),(7,6,1,6,6,29,'Quadratic equations: four methods',NULL,NULL,'Method 2: Factoring','Write the equation in standard form, factor the left side, then use the zero product property: if $pq = 0$, then $p = 0$ or $q = 0$.','2026-10-20 23:24:18'),(8,6,2,6,6,32,'Quadratic equations: four methods',NULL,NULL,'The discriminant','It tells you the nature of the roots before you solve:','2026-10-20 23:24:18'),(9,6,3,6,6,33,'Quadratic equations: four methods',NULL,NULL,'Choosing a method','Factoring is efficient when the trinomial factors easily over the integers.','2026-10-20 23:24:18'),(10,8,1,1,1,3,'Breathing and circulation notes',NULL,NULL,'Gas exchange in the alveoli','Oxygen diffuses from the air in the alveoli, where its concentration is high, into the blood, where its concentration is lower.','2026-10-20 23:35:34'),(11,14,1,6,6,27,'Quadratic equations: four methods',NULL,NULL,'What makes an equation quadratic','A quadratic equation has at most two real solutions, also called roots.','2026-10-21 01:18:27'),(12,14,2,6,6,28,'Quadratic equations: four methods',NULL,NULL,'Method 1: Extracting square roots','Remember that a positive number has two square roots.','2026-10-21 01:18:27'),(13,14,3,6,6,29,'Quadratic equations: four methods',NULL,NULL,'Method 2: Factoring','Always check by substituting.','2026-10-21 01:18:27'),(14,14,4,6,6,30,'Quadratic equations: four methods',NULL,NULL,'Method 3: Completing the square','Rewrite the equation so that one side is a perfect square trinomial.','2026-10-21 01:18:27'),(15,20,1,8,8,41,'Making inferences while reading',NULL,NULL,'What an inference is','Writers do not state everything directly.','2026-10-22 19:46:58'),(16,20,2,8,8,42,'Making inferences while reading',NULL,NULL,'Clues plus knowledge','A useful formula is: text clues + what I know = inference.','2026-10-22 19:46:58'),(17,20,3,8,8,43,'Making inferences while reading',NULL,NULL,'Steps for making an inference','Ask a question that the text does not answer directly, such as \"Why did the character leave early?\"','2026-10-22 19:46:58'),(18,20,4,8,8,44,'Making inferences while reading',NULL,NULL,'A short practice passage','From the clues \"for the third time that week\", the repeated glances at her watch and the tapping foot, together with what we know about waiting for public transport, we can infer that Mara is worried about being late.','2026-10-22 19:46:58'),(19,22,1,8,8,41,'Making inferences while reading',NULL,NULL,'What an inference is','An inference is a logical conclusion you reach by combining clues in a text with what you already know.','2026-10-22 19:47:20'),(20,22,2,8,8,42,'Making inferences while reading',NULL,NULL,'Clues plus knowledge','A useful formula is: text clues + what I know = inference.','2026-10-22 19:47:20'),(21,22,3,8,8,43,'Making inferences while reading',NULL,NULL,'Steps for making an inference','Connect the clues to what you already know.','2026-10-22 19:47:20'),(22,22,4,8,8,44,'Making inferences while reading',NULL,NULL,'A short practice passage','When the jeep finally came, she let two older women board first, then squeezed into the last seat near the door.','2026-10-22 19:47:20'),(23,28,1,10,9,47,'Algebra',NULL,NULL,'A Quick Guide to Algebra','Algebra uses letters (called variables) to represent numbers.','2026-10-22 20:00:03'),(24,28,2,10,9,48,'Algebra',NULL,NULL,'1. Know the key parts','A statement that two sides are equal, like x + 3 = 8.','2026-10-22 20:00:03'),(25,28,3,10,9,49,'Algebra',NULL,NULL,'2. How to solve equations','Subtract 3 from both sides.','2026-10-22 20:00:03'),(26,28,4,10,9,50,'Algebra',NULL,NULL,'3. Simplify like terms','Like terms have the same variable part.','2026-10-22 20:00:03'),(27,30,1,10,9,47,'Algebra',NULL,NULL,'A Quick Guide to Algebra','Algebra uses letters (called variables) to represent numbers.','2026-10-23 03:55:27'),(28,30,2,10,9,48,'Algebra',NULL,NULL,'1. Know the key parts','A statement that two sides are equal, like x + 3 = 8.','2026-10-23 03:55:27'),(29,30,3,10,9,49,'Algebra',NULL,NULL,'2. How to solve equations','Subtract 3 from both sides.','2026-10-23 03:55:27'),(30,30,4,10,9,50,'Algebra',NULL,NULL,'3. Simplify like terms','Like terms have the same variable part.','2026-10-23 03:55:27'),(31,32,1,5,5,18,'Breathing and circulation notes',NULL,NULL,'Why your body needs both systems','Neither system can do the job alone.','2026-10-23 04:08:17'),(32,32,2,5,5,19,'Breathing and circulation notes',NULL,NULL,'The path air takes','Inside the lungs the bronchi branch into smaller and smaller tubes called bronchioles, which end in clusters of tiny air sacs called alveoli.','2026-10-23 04:08:17'),(33,32,3,5,5,20,'Breathing and circulation notes',NULL,NULL,'Gas exchange in the alveoli','Three features make this exchange fast: the very large total surface area of the alveoli, their thin walls, and their moist lining, which lets gases dissolve before they diffuse.','2026-10-23 04:08:17'),(34,32,4,5,5,21,'Breathing and circulation notes',NULL,NULL,'How breathing works','When you exhale, the diaphragm relaxes and moves back up, the rib cage moves down and in, the chest cavity gets smaller, and air is pushed out.','2026-10-23 04:08:17'),(35,34,1,2,2,12,'Heredity notes',3,3,NULL,'Geneticists write the dominant allele with a capital letter and the recessive allele with the same letter in lowercase.','2026-10-23 04:10:04');
