INSERT INTO `announcements` VALUES (1,1,1,2,'Bring a stopwatch on Monday','For the breathing-rate lab, bring a stopwatch or a phone with a timer. You will work in pairs, so agree with your partner who brings it.','2026-10-17 23:24:16','2026-10-17 23:24:16'),(2,1,3,3,'Factoring quiz results are out','Scores and comments are now visible on the quiz page. If a step confuses you, compare it with Method 2 in the notes before Friday\'s class.','2026-10-20 03:24:16','2026-10-20 03:24:16'),(3,1,5,4,'Library visit on Thursday','We will meet at the library for the first 20 minutes of class. Bring your inference journal.','2026-10-18 23:24:16','2026-10-18 23:24:16');
