INSERT INTO `assignment_versions` VALUES (1,1,1,'{\"title\":\"Respiratory and circulatory systems check\",\"points_possible\":7,\"questions\":[{\"id\":1,\"qtype\":\"multiple_choice\",\"prompt\":\"Where does gas exchange between the air and the blood take place?\",\"points\":1,\"options\":[{\"key\":\"A\",\"text\":\"Trachea\"},{\"key\":\"B\",\"text\":\"Bronchi\"},{\"key\":\"C\",\"text\":\"Alveoli\"},{\"key\":\"D\",\"text\":\"Larynx\"}],\"answer_key\":{\"correct\":\"C\"},\"explanation\":\"Gases diffuse across the thin walls of the alveoli into and out of the surrounding capillaries.\",\"topic\":\"Gas exchange\"},{\"id\":2,\"qtype\":\"multiple_choice\",\"prompt\":\"Which chamber of the heart pumps oxygen-rich blood to the rest of the body?\",\"points\":1,\"options\":[{\"key\":\"A\",\"text\":\"Right atrium\"},{\"key\":\"B\",\"text\":\"Right ventricle\"},{\"key\":\"C\",\"text\":\"Left atrium\"},{\"key\":\"D\",\"text\":\"Left ventricle\"}],\"answer_key\":{\"correct\":\"D\"},\"explanation\":\"The left ventricle has the thickest wall because it pumps blood around the whole body.\",\"topic\":\"The heart\"},{\"id\":3,\"qtype\":\"true_false\",\"prompt\":\"Veins carry blood away from the heart.\",\"points\":1,\"options\":[],\"answer_key\":{\"correct\":false},\"explanation\":\"Arteries carry blood away from the heart; veins carry it back.\",\"topic\":\"Blood vessels\"},{\"id\":4,\"qtype\":\"multiple_choice\",\"prompt\":\"Why do oxygen and carbon dioxide move across the walls of the alveoli so easily?\",\"points\":2,\"options\":[{\"key\":\"A\",\"text\":\"The walls are thick and muscular\"},{\"key\":\"B\",\"text\":\"The walls are one cell thick and moist\"},{\"key\":\"C\",\"text\":\"The alveoli contain valves\"},{\"key\":\"D\",\"text\":\"The air in the alveoli is under high pressure\"}],\"answer_key\":{\"correct\":\"B\"},\"explanation\":\"Thin, moist walls and a large surface area let the gases diffuse quickly.\",\"topic\":\"Gas exchange\"},{\"id\":5,\"qtype\":\"true_false\",\"prompt\":\"When you inhale, the diaphragm contracts and moves down.\",\"points\":1,\"options\":[],\"answer_key\":{\"correct\":true},\"explanation\":\"The contracting diaphragm flattens, making the chest cavity larger so air flows in.\",\"topic\":\"Breathing\"},{\"id\":6,\"qtype\":\"short_answer\",\"prompt\":\"Name the tiny blood vessels where substances pass between the blood and the body\'s cells.\",\"points\":1,\"options\":[],\"answer_key\":{\"accepted\":[\"capillaries\",\"capillary\"],\"case_sensitive\":false},\"explanation\":\"Capillaries have walls one cell thick.\",\"topic\":\"Blood vessels\"}]}',2,'2026-10-20 23:24:16'),(2,2,1,'{\"title\":\"Lab report: breathing rate before and after exercise\",\"points_possible\":10,\"questions\":[]}',2,'2026-10-20 23:24:16'),(3,3,1,'{\"title\":\"Heredity basics\",\"points_possible\":8,\"questions\":[{\"id\":7,\"qtype\":\"multiple_choice\",\"prompt\":\"Two heterozygous tall pea plants (Tt) are crossed. What is the probability that an offspring is short?\",\"points\":1,\"options\":[{\"key\":\"A\",\"text\":\"0\"},{\"key\":\"B\",\"text\":\"1 in 4\"},{\"key\":\"C\",\"text\":\"1 in 2\"},{\"key\":\"D\",\"text\":\"3 in 4\"}],\"answer_key\":{\"correct\":\"B\"},\"explanation\":\"The cross gives TT, Tt, Tt and tt; only tt is short, so 1 in 4.\",\"topic\":\"Punnett squares\"},{\"id\":8,\"qtype\":\"true_false\",\"prompt\":\"A person with type AB blood shows both the A and the B allele because they are codominant.\",\"points\":1,\"options\":[],\"answer_key\":{\"correct\":true},\"explanation\":\"In codominance both alleles are fully expressed.\",\"topic\":\"Non-Mendelian inheritance\"},{\"id\":9,\"qtype\":\"multiple_choice\",\"prompt\":\"What do we call the trait that an organism shows?\",\"points\":1,\"options\":[{\"key\":\"A\",\"text\":\"Genotype\"},{\"key\":\"B\",\"text\":\"Phenotype\"},{\"key\":\"C\",\"text\":\"Allele\"},{\"key\":\"D\",\"text\":\"Gamete\"}],\"answer_key\":{\"correct\":\"B\"},\"explanation\":\"The phenotype is the observable trait; the genotype is the allele combination.\",\"topic\":\"Vocabulary\"},{\"id\":10,\"qtype\":\"short_answer\",\"prompt\":\"What is the term for different versions of the same gene?\",\"points\":1,\"options\":[],\"answer_key\":{\"accepted\":[\"alleles\",\"allele\"],\"case_sensitive\":false},\"explanation\":\"Different versions of a gene are alleles.\",\"topic\":\"Vocabulary\"},{\"id\":11,\"qtype\":\"essay\",\"prompt\":\"In three or four sentences, explain how two tall parent plants can have a short offspring.\",\"points\":4,\"options\":[],\"answer_key\":[],\"explanation\":null,\"topic\":\"Punnett squares\"}]}',2,'2026-10-20 23:24:16'),(4,5,1,'{\"title\":\"Respiratory and circulatory systems check\",\"points_possible\":7,\"questions\":[{\"id\":12,\"qtype\":\"multiple_choice\",\"prompt\":\"Where does gas exchange between the air and the blood take place?\",\"points\":1,\"options\":[{\"key\":\"A\",\"text\":\"Trachea\"},{\"key\":\"B\",\"text\":\"Bronchi\"},{\"key\":\"C\",\"text\":\"Alveoli\"},{\"key\":\"D\",\"text\":\"Larynx\"}],\"answer_key\":{\"correct\":\"C\"},\"explanation\":\"Gases diffuse across the thin walls of the alveoli into and out of the surrounding capillaries.\",\"topic\":\"Gas exchange\"},{\"id\":13,\"qtype\":\"multiple_choice\",\"prompt\":\"Which chamber of the heart pumps oxygen-rich blood to the rest of the body?\",\"points\":1,\"options\":[{\"key\":\"A\",\"text\":\"Right atrium\"},{\"key\":\"B\",\"text\":\"Right ventricle\"},{\"key\":\"C\",\"text\":\"Left atrium\"},{\"key\":\"D\",\"text\":\"Left ventricle\"}],\"answer_key\":{\"correct\":\"D\"},\"explanation\":\"The left ventricle has the thickest wall because it pumps blood around the whole body.\",\"topic\":\"The heart\"},{\"id\":14,\"qtype\":\"true_false\",\"prompt\":\"Veins carry blood away from the heart.\",\"points\":1,\"options\":[],\"answer_key\":{\"correct\":false},\"explanation\":\"Arteries carry blood away from the heart; veins carry it back.\",\"topic\":\"Blood vessels\"},{\"id\":15,\"qtype\":\"multiple_choice\",\"prompt\":\"Why do oxygen and carbon dioxide move across the walls of the alveoli so easily?\",\"points\":2,\"options\":[{\"key\":\"A\",\"text\":\"The walls are thick and muscular\"},{\"key\":\"B\",\"text\":\"The walls are one cell thick and moist\"},{\"key\":\"C\",\"text\":\"The alveoli contain valves\"},{\"key\":\"D\",\"text\":\"The air in the alveoli is under high pressure\"}],\"answer_key\":{\"correct\":\"B\"},\"explanation\":\"Thin, moist walls and a large surface area let the gases diffuse quickly.\",\"topic\":\"Gas exchange\"},{\"id\":16,\"qtype\":\"true_false\",\"prompt\":\"When you inhale, the diaphragm contracts and moves down.\",\"points\":1,\"options\":[],\"answer_key\":{\"correct\":true},\"explanation\":\"The contracting diaphragm flattens, making the chest cavity larger so air flows in.\",\"topic\":\"Breathing\"},{\"id\":17,\"qtype\":\"short_answer\",\"prompt\":\"Name the tiny blood vessels where substances pass between the blood and the body\'s cells.\",\"points\":1,\"options\":[],\"answer_key\":{\"accepted\":[\"capillaries\",\"capillary\"],\"case_sensitive\":false},\"explanation\":\"Capillaries have walls one cell thick.\",\"topic\":\"Blood vessels\"}]}',2,'2026-10-20 23:24:16'),(5,6,1,'{\"title\":\"Solving quadratic equations by factoring\",\"points_possible\":7,\"questions\":[{\"id\":18,\"qtype\":\"multiple_choice\",\"prompt\":\"Which equation is quadratic?\",\"points\":1,\"options\":[{\"key\":\"A\",\"text\":\"3x + 2 = 0\"},{\"key\":\"B\",\"text\":\"x^2 - 4x + 3 = 0\"},{\"key\":\"C\",\"text\":\"x^3 = 8\"},{\"key\":\"D\",\"text\":\"2\\/x = 5\"}],\"answer_key\":{\"correct\":\"B\"},\"explanation\":\"The highest power of x is 2.\",\"topic\":\"Standard form\"},{\"id\":19,\"qtype\":\"multiple_choice\",\"prompt\":\"Solve by factoring: x^2 + 5x + 6 = 0\",\"points\":2,\"options\":[{\"key\":\"A\",\"text\":\"x = 2 or x = 3\"},{\"key\":\"B\",\"text\":\"x = -2 or x = -3\"},{\"key\":\"C\",\"text\":\"x = -1 or x = -6\"},{\"key\":\"D\",\"text\":\"x = 1 or x = 6\"}],\"answer_key\":{\"correct\":\"B\"},\"explanation\":\"(x + 2)(x + 3) = 0, so x = -2 or x = -3.\",\"topic\":\"Factoring\"},{\"id\":20,\"qtype\":\"multiple_choice\",\"prompt\":\"Solve by factoring: x^2 - 7x + 10 = 0\",\"points\":2,\"options\":[{\"key\":\"A\",\"text\":\"x = 2 or x = 5\"},{\"key\":\"B\",\"text\":\"x = -2 or x = -5\"},{\"key\":\"C\",\"text\":\"x = 1 or x = 10\"},{\"key\":\"D\",\"text\":\"x = -1 or x = -10\"}],\"answer_key\":{\"correct\":\"A\"},\"explanation\":\"(x - 2)(x - 5) = 0.\",\"topic\":\"Factoring\"},{\"id\":21,\"qtype\":\"true_false\",\"prompt\":\"If (x - 4)(x + 1) = 0, then x = 4 or x = -1.\",\"points\":1,\"options\":[],\"answer_key\":{\"correct\":true},\"explanation\":\"Set each factor equal to zero.\",\"topic\":\"Zero product property\"},{\"id\":22,\"qtype\":\"short_answer\",\"prompt\":\"What is the positive solution of x^2 - 49 = 0?\",\"points\":1,\"options\":[],\"answer_key\":{\"accepted\":[\"7\",\"x = 7\",\"x=7\"],\"case_sensitive\":false},\"explanation\":\"x^2 = 49, so x = 7 or x = -7.\",\"topic\":\"Extracting square roots\"}]}',3,'2026-10-20 23:24:16'),(6,7,1,'{\"title\":\"Choosing a method: explain your reasoning\",\"points_possible\":10,\"questions\":[]}',3,'2026-10-20 23:24:16'),(7,8,1,'{\"title\":\"Solving quadratic equations by factoring\",\"points_possible\":7,\"questions\":[{\"id\":23,\"qtype\":\"multiple_choice\",\"prompt\":\"Which equation is quadratic?\",\"points\":1,\"options\":[{\"key\":\"A\",\"text\":\"3x + 2 = 0\"},{\"key\":\"B\",\"text\":\"x^2 - 4x + 3 = 0\"},{\"key\":\"C\",\"text\":\"x^3 = 8\"},{\"key\":\"D\",\"text\":\"2\\/x = 5\"}],\"answer_key\":{\"correct\":\"B\"},\"explanation\":\"The highest power of x is 2.\",\"topic\":\"Standard form\"},{\"id\":24,\"qtype\":\"multiple_choice\",\"prompt\":\"Solve by factoring: x^2 + 5x + 6 = 0\",\"points\":2,\"options\":[{\"key\":\"A\",\"text\":\"x = 2 or x = 3\"},{\"key\":\"B\",\"text\":\"x = -2 or x = -3\"},{\"key\":\"C\",\"text\":\"x = -1 or x = -6\"},{\"key\":\"D\",\"text\":\"x = 1 or x = 6\"}],\"answer_key\":{\"correct\":\"B\"},\"explanation\":\"(x + 2)(x + 3) = 0, so x = -2 or x = -3.\",\"topic\":\"Factoring\"},{\"id\":25,\"qtype\":\"multiple_choice\",\"prompt\":\"Solve by factoring: x^2 - 7x + 10 = 0\",\"points\":2,\"options\":[{\"key\":\"A\",\"text\":\"x = 2 or x = 5\"},{\"key\":\"B\",\"text\":\"x = -2 or x = -5\"},{\"key\":\"C\",\"text\":\"x = 1 or x = 10\"},{\"key\":\"D\",\"text\":\"x = -1 or x = -10\"}],\"answer_key\":{\"correct\":\"A\"},\"explanation\":\"(x - 2)(x - 5) = 0.\",\"topic\":\"Factoring\"},{\"id\":26,\"qtype\":\"true_false\",\"prompt\":\"If (x - 4)(x + 1) = 0, then x = 4 or x = -1.\",\"points\":1,\"options\":[],\"answer_key\":{\"correct\":true},\"explanation\":\"Set each factor equal to zero.\",\"topic\":\"Zero product property\"},{\"id\":27,\"qtype\":\"short_answer\",\"prompt\":\"What is the positive solution of x^2 - 49 = 0?\",\"points\":1,\"options\":[],\"answer_key\":{\"accepted\":[\"7\",\"x = 7\",\"x=7\"],\"case_sensitive\":false},\"explanation\":\"x^2 = 49, so x = 7 or x = -7.\",\"topic\":\"Extracting square roots\"}]}',3,'2026-10-20 23:24:16'),(8,9,1,'{\"title\":\"Reading response: The jeepney stop\",\"points_possible\":10,\"questions\":[]}',4,'2026-10-20 23:24:16'),(9,10,1,'{\"title\":\"Inference journal: three clues\",\"points_possible\":10,\"questions\":[]}',4,'2026-10-20 23:24:16'),(10,11,1,'{\"title\":\"Short test on paper: breathing and circulation\",\"points_possible\":20,\"questions\":[{\"id\":28,\"qtype\":\"multiple_choice\",\"prompt\":\"Which structure carries air from the larynx to the bronchi?\",\"points\":2,\"options\":[{\"key\":\"A\",\"text\":\"Trachea\"},{\"key\":\"B\",\"text\":\"Alveoli\"},{\"key\":\"C\",\"text\":\"Diaphragm\"},{\"key\":\"D\",\"text\":\"Capillaries\"}],\"answer_key\":{\"correct\":\"A\"},\"explanation\":null,\"topic\":\"Breathing\"},{\"id\":29,\"qtype\":\"multiple_choice\",\"prompt\":\"Which blood vessels carry blood back to the heart?\",\"points\":2,\"options\":[{\"key\":\"A\",\"text\":\"Arteries\"},{\"key\":\"B\",\"text\":\"Veins\"},{\"key\":\"C\",\"text\":\"Capillaries\"},{\"key\":\"D\",\"text\":\"Alveoli\"}],\"answer_key\":{\"correct\":\"B\"},\"explanation\":null,\"topic\":\"Blood vessels\"},{\"id\":30,\"qtype\":\"multiple_choice\",\"prompt\":\"What does the right ventricle pump blood to?\",\"points\":2,\"options\":[{\"key\":\"A\",\"text\":\"The brain\"},{\"key\":\"B\",\"text\":\"The lungs\"},{\"key\":\"C\",\"text\":\"The liver\"},{\"key\":\"D\",\"text\":\"The arms and legs\"}],\"answer_key\":{\"correct\":\"B\"},\"explanation\":null,\"topic\":\"The heart\"},{\"id\":31,\"qtype\":\"true_false\",\"prompt\":\"The diaphragm relaxes and moves up when you exhale.\",\"points\":2,\"options\":[],\"answer_key\":{\"correct\":true},\"explanation\":null,\"topic\":\"Breathing\"},{\"id\":32,\"qtype\":\"true_false\",\"prompt\":\"Capillary walls are many cells thick.\",\"points\":2,\"options\":[],\"answer_key\":{\"correct\":false},\"explanation\":null,\"topic\":\"Blood vessels\"},{\"id\":33,\"qtype\":\"short_answer\",\"prompt\":\"Name the gas that the blood picks up in the alveoli.\",\"points\":2,\"options\":[],\"answer_key\":{\"accepted\":[\"oxygen\"],\"case_sensitive\":false},\"explanation\":null,\"topic\":\"Gas exchange\"},{\"id\":34,\"qtype\":\"essay\",\"prompt\":\"Explain how the respiratory and circulatory systems work together to deliver oxygen to a muscle cell.\",\"points\":8,\"options\":[],\"answer_key\":[],\"explanation\":null,\"topic\":\"Gas exchange\"}]}',2,'2026-10-20 23:24:17'),(11,12,1,'{\"title\":\"Performance task in class: model of the lungs\",\"points_possible\":20,\"questions\":[]}',2,'2026-10-20 23:24:17'),(12,16,1,'{\"title\":\"Photosynthesis\",\"points_possible\":20,\"questions\":[]}',2,'2026-10-22 19:54:39');
