INSERT INTO `assignments` VALUES (1,1,1,1,'quiz','Respiratory and circulatory systems check','Answer all six questions. You have 20 minutes once you start, and two attempts. Your best attempt counts.\n\nThe notes on gas exchange and blood vessels will help.','Explain gas exchange; identify the parts of the heart and blood vessels.','written',NULL,'published','2026-10-14 23:00:00','2026-10-19 15:59:00','not_accepted',0,2,20,7.00,0,0,0,NULL,'manual','after_due',NULL,0,1,2,NULL,'2026-10-14 07:30:00',NULL,'2026-10-14 07:30:00','2026-10-20 23:24:16'),(2,1,1,1,'assignment','Lab report: breathing rate before and after exercise','Work with your partner to count breaths per minute at rest, right after two minutes of jumping jacks, and after five minutes of rest.\n\nIn your report:\n\n1. Record your data in a table.\n2. Describe the pattern you see.\n3. Explain the pattern using **both** the respiratory and the circulatory systems.\n4. Write one question you would test next.\n\nYou may type your report below, attach a photo of your table, or both.','Collect and present data; explain how the two systems respond to exercise.','performance',NULL,'published','2026-10-15 23:00:00','2026-10-23 15:59:00','penalty',10,1,NULL,10.00,1,1,0,'[{\"id\":\"c1\",\"title\":\"Data and observations\",\"points\":4,\"description\":\"Accurate table with all three readings and a clear description of the pattern.\"},{\"id\":\"c2\",\"title\":\"Explanation using both body systems\",\"points\":4,\"description\":\"Links breathing rate and heart rate to the muscles\' need for oxygen.\"},{\"id\":\"c3\",\"title\":\"Next question\",\"points\":2,\"description\":\"A testable question that follows from the results.\"}]','manual','never',NULL,0,2,2,NULL,'2026-10-15 23:00:00',NULL,'2026-10-15 23:00:00','2026-10-20 23:24:16'),(3,1,1,2,'quiz','Heredity basics','Five questions on the heredity notes. The last question is written and will be read by your teacher. 20 minutes, one attempt.',NULL,'written',NULL,'published','2026-10-20 21:24:16','2026-10-27 15:59:00','accepted',0,1,20,8.00,0,0,0,NULL,'manual','after_due',NULL,0,3,2,NULL,'2026-10-20 08:00:00',NULL,'2026-10-20 08:00:00','2026-10-20 23:24:16'),(4,1,1,1,'assignment','Concept map: from air to cell','Draw a concept map that follows one oxygen molecule from the air to a muscle cell.',NULL,'performance',NULL,'draft',NULL,'2026-10-30 15:59:00','accepted',0,1,NULL,10.00,0,1,0,NULL,'manual','after_due',NULL,0,NULL,2,NULL,NULL,NULL,'2026-10-06 23:24:16','2026-10-06 23:24:16'),(5,1,2,3,'quiz','Respiratory and circulatory systems check','Answer all six questions. You have 20 minutes once you start, and two attempts. Your best attempt counts.\n\nThe notes on gas exchange and blood vessels will help.',NULL,'written',NULL,'published','2026-10-14 23:00:00','2026-10-19 15:59:00','not_accepted',0,2,20,7.00,0,0,0,NULL,'manual','after_due',NULL,0,4,2,NULL,'2026-10-14 07:40:00',NULL,'2026-10-14 07:40:00','2026-10-20 23:24:16'),(6,1,3,5,'quiz','Solving quadratic equations by factoring','Five questions. Show your work on scratch paper; only the final answer is recorded here.',NULL,'written',NULL,'published','2026-10-11 23:00:00','2026-10-20 13:00:00','not_accepted',0,1,25,7.00,0,0,0,NULL,'manual','after_due',NULL,0,5,3,NULL,'2026-10-11 06:00:00',NULL,'2026-10-11 06:00:00','2026-10-20 23:24:16'),(7,1,3,5,'assignment','Choosing a method: explain your reasoning','Solve each equation using the method you think is best, and explain in one or two sentences why you chose it.\n\n1. $x^2 - 81 = 0$\n2. $x^2 + 3x - 10 = 0$\n3. $2x^2 + 3x - 4 = 0$',NULL,'performance',NULL,'published','2026-10-18 23:00:00','2026-10-25 15:59:00','accepted',0,1,NULL,10.00,1,1,0,'[{\"id\":\"c1\",\"title\":\"Correct solutions\",\"points\":6,\"description\":\"Two points per equation, including both roots where they exist.\"},{\"id\":\"c2\",\"title\":\"Reasoning\",\"points\":4,\"description\":\"Explains why the method fits each equation.\"}]','manual','never',NULL,0,6,3,NULL,'2026-10-18 23:00:00',NULL,'2026-10-18 23:00:00','2026-10-20 23:24:16'),(8,1,4,6,'quiz','Solving quadratic equations by factoring','Five questions on factoring.',NULL,'written',NULL,'published','2026-10-21 23:00:00','2026-10-26 13:00:00','accepted',0,1,25,7.00,0,0,0,NULL,'manual','after_due',NULL,0,7,3,NULL,'2026-10-20 21:24:16',NULL,'2026-10-20 21:24:16','2026-10-20 23:24:16'),(9,1,5,7,'assignment','Reading response: The jeepney stop','Read the practice passage in \"Making inferences while reading\". What can you infer about Mara? Support your inference with at least two clues from the text.',NULL,'written',NULL,'published','2026-10-11 23:00:00','2026-10-16 15:59:00','accepted',0,1,NULL,10.00,1,0,0,'[{\"id\":\"c1\",\"title\":\"Inference\",\"points\":4,\"description\":\"States a reasonable inference that goes beyond what the text says directly.\"},{\"id\":\"c2\",\"title\":\"Evidence\",\"points\":4,\"description\":\"Uses at least two specific clues from the passage.\"},{\"id\":\"c3\",\"title\":\"Clarity\",\"points\":2,\"description\":\"Clear, complete sentences.\"}]','manual','never',NULL,0,8,4,NULL,'2026-10-11 23:00:00',NULL,'2026-10-11 23:00:00','2026-10-20 23:24:16'),(10,1,5,7,'assignment','Inference journal: three clues','Choose a short story or a news article you read this week. Write down three clues from it and the inference each clue supports. Use the clue + what I know = inference formula.',NULL,'performance',NULL,'published','2026-10-13 23:00:00','2026-10-22 13:00:00','penalty',10,1,NULL,10.00,1,0,0,'[{\"id\":\"c1\",\"title\":\"Three clue–inference pairs\",\"points\":6,\"description\":\"Each clue is quoted and leads to a reasonable inference.\"},{\"id\":\"c2\",\"title\":\"Use of the formula\",\"points\":2,\"description\":\"Shows the clue + what I know = inference reasoning.\"},{\"id\":\"c3\",\"title\":\"Clarity\",\"points\":2,\"description\":\"Clear, complete sentences.\"}]','manual','never',NULL,0,9,4,NULL,'2026-10-13 23:00:00',NULL,'2026-10-13 23:00:00','2026-10-20 23:24:16'),(11,1,1,1,'paper','Short test on paper: breathing and circulation','Written in class. Answer all questions on the test paper; the last question needs a short paragraph.',NULL,'periodic',NULL,'published',NULL,'2026-10-18 02:00:00','accepted',0,1,NULL,20.00,0,0,0,NULL,'manual','never',NULL,0,10,2,NULL,'2026-10-10 23:00:00',NULL,'2026-10-10 23:00:00','2026-10-20 23:24:17'),(12,1,1,1,'paper','Performance task in class: model of the lungs','In groups, you will build a working model of the lungs from a plastic bottle, balloons and a rubber sheet, then explain how it shows breathing in and out.\n\nBring: one 1.5-litre plastic bottle and two balloons.',NULL,'performance',NULL,'published',NULL,'2026-10-26 05:00:00','accepted',0,1,NULL,20.00,0,0,0,'[{\"id\":\"c1\",\"title\":\"Working model\",\"points\":8,\"description\":\"The model shows the lungs filling and emptying as the sheet moves.\"},{\"id\":\"c2\",\"title\":\"Explanation\",\"points\":8,\"description\":\"Explains how the diaphragm changes the space in the chest.\"},{\"id\":\"c3\",\"title\":\"Teamwork and care\",\"points\":4,\"description\":\"Everyone takes part; materials are handled safely.\"}]','manual','never',NULL,0,11,2,NULL,'2026-10-18 23:00:00',NULL,'2026-10-18 23:00:00','2026-10-20 23:24:17'),(13,1,1,NULL,'quiz','Usability check quiz: heredity',NULL,NULL,NULL,NULL,'draft',NULL,'2026-10-30 15:59:00','accepted',0,1,NULL,5.00,0,0,0,NULL,'manual','after_due',NULL,1,NULL,2,NULL,NULL,NULL,'2026-10-20 23:37:57','2026-10-20 23:39:01'),(16,1,2,NULL,'assignment','Photosynthesis','Must be analyze and explain what is photosynthesis',NULL,'written',1,'published','2026-10-23 19:53:00','2026-10-24 19:54:00','accepted',0,1,NULL,20.00,1,0,0,NULL,'manual','never',NULL,0,12,2,NULL,'2026-10-22 19:54:39',NULL,'2026-10-22 19:54:26','2026-10-22 19:54:39'),(17,1,2,NULL,'quiz','asdas','sadas',NULL,'written',NULL,'draft',NULL,'2026-10-23 19:54:00','accepted',0,1,NULL,0.00,0,0,0,NULL,'manual','manual',NULL,0,NULL,2,NULL,NULL,NULL,'2026-10-22 19:55:06','2026-10-22 19:55:06');
