INSERT INTO `learning_materials` VALUES (1,1,1,1,'Breathing and circulation notes','Read before the breathing-rate lab. Sections 3 and 7 are on the quiz.','Respiratory and circulatory systems','file',NULL,'published',NULL,1,1,2,NULL,'2026-10-08 23:24:15','2026-10-08 23:24:15','2026-10-08 23:24:15'),(2,1,1,2,'Heredity notes','Four pages: genes and chromosomes, Mendel, Punnett squares, and patterns beyond simple dominance.','Heredity','file',NULL,'published',NULL,1,2,2,NULL,'2026-10-18 23:24:15','2026-10-18 23:24:15','2026-10-18 23:24:15'),(3,1,1,2,'Module 2 review sheet',NULL,'Heredity','file',NULL,'published','2026-10-23 23:00:00',1,3,2,NULL,'2026-10-19 23:24:15','2026-10-19 23:24:15','2026-10-19 23:24:15'),(4,1,1,1,'Lab safety reminders',NULL,'Lab safety','file',NULL,'draft',NULL,0,4,2,NULL,NULL,'2026-10-19 23:24:16','2026-10-19 23:24:16'),(5,1,2,3,'Breathing and circulation notes',NULL,'Respiratory and circulatory systems','file',NULL,'published',NULL,1,5,2,NULL,'2026-10-08 23:24:16','2026-10-08 23:24:16','2026-10-08 23:24:16'),(6,1,3,5,'Quadratic equations: four methods','Worked examples for each method, plus the discriminant.','Quadratic equations','file',NULL,'published',NULL,1,6,3,NULL,'2026-10-12 23:24:16','2026-10-12 23:24:16','2026-10-12 23:24:16'),(7,1,4,6,'Quadratic equations: four methods',NULL,'Quadratic equations','file',NULL,'published',NULL,1,7,3,NULL,'2026-10-12 23:24:16','2026-10-12 23:24:16','2026-10-12 23:24:16'),(8,1,5,7,'Making inferences while reading',NULL,'Making inferences','file',NULL,'published',NULL,1,8,4,NULL,'2026-10-14 23:24:16','2026-10-14 23:24:16','2026-10-14 23:24:16'),(9,1,3,5,'Graph quadratic functions with Desmos','Type y = x^2 + 5x + 6 and find where the graph crosses the x-axis.','Quadratic equations','link','https://www.desmos.com/calculator','published',NULL,0,NULL,3,NULL,'2026-10-12 23:24:16','2026-10-12 23:24:16','2026-10-20 23:24:16'),(10,1,2,NULL,'Algebra',NULL,NULL,'file',NULL,'draft',NULL,1,9,2,NULL,NULL,'2026-10-22 1