INSERT INTO `lessons` VALUES (1,1,1,1,'Gas exchange in the alveoli','published','Grade 9',50,'Grade 9','en','Discussion and pair work','- Describe the structure of the alveoli.\n- Explain how oxygen and carbon dioxide move between the alveoli and the blood.','{\"objectives\":\"- Describe the structure of the alveoli.\\n- Explain how oxygen and carbon dioxide move between the alveoli and the blood.\",\"prior_knowledge\":\"You know that the body needs oxygen and that air enters through the nose and mouth.\",\"explanation\":\"Air reaches the alveoli through the bronchioles. Each alveolus has a wall one cell thick and is wrapped in capillaries. Oxygen moves from high concentration in the alveoli to lower concentration in the blood by **diffusion**; carbon dioxide moves the opposite way. [1]\",\"worked_example\":\"**Question:** why would gas exchange slow down if the alveolar walls became thicker?\\n\\n**Answer:** the gases would have farther to diffuse, so less oxygen would reach the blood each second.\",\"activities\":\"1. Pairs sketch an alveolus and its capillaries and label the direction each gas moves.\\n2. Groups compare a sponge and a solid block to discuss why surface area matters.\",\"checks\":\"- Which way does carbon dioxide move, and why?\\n- Name two features that make gas exchange fast.\",\"exit_ticket\":\"In one sentence, explain why the alveolar wall is only one cell thick.\",\"sources\":[{\"n\":1,\"material_id\":1,\"title\":\"Breathing and circulation notes\",\"where\":\"Gas exchange in the alveoli\"}]}','{\"objectives\":\"- Describe the structure of the alveoli.\\n- Explain how oxygen and carbon dioxide move between the alveoli and the blood.\",\"prior_knowledge\":\"You know that the body needs oxygen and that air enters through the nose and mouth.\",\"explanation\":\"Air reaches the alveoli through the bronchioles. Each alveolus has a wall one cell thick and is wrapped in capillaries. Oxygen moves from high concentration in the alveoli to lower concentration in the blood by **diffusion**; carbon dioxide moves the opposite way. [1]\",\"worked_example\":\"**Question:** why would gas exchange slow down if the alveolar walls became thicker?\\n\\n**Answer:** the gases would have farther to diffuse, so less oxygen would reach the blood each second.\",\"activities\":\"1. Pairs sketch an alveolus and its capillaries and label the direction each gas moves.\\n2. Groups compare a sponge and a solid block to discuss why surface area matters.\",\"checks\":\"- Which way does carbon dioxide move, and why?\\n- Name two features that make gas exchange fast.\",\"exit_ticket\":\"In one sentence, explain why the alveolar wall is only one cell thick.\",\"sources\":[{\"n\":1,\"material_id\":1,\"title\":\"Breathing and circulation notes\",\"where\":\"Gas exchange in the alveoli\"}]}','[1]',0,0,2,NULL,2,'2026-10-10 23:24:16','2026-10-09 23:24:16','2026-10-10 23:24:16'),(2,1,1,2,'Punnett squares in practice','draft','Grade 9',50,NULL,'en',NULL,'- Use a Punnett square to predict offspring genotypes.\n- Express results as ratios and probabilities.','{\"objectives\":\"- Use a Punnett square to predict offspring genotypes.\\n- Express results as ratios and probabilities.\",\"prior_knowledge\":\"Dominant and recessive alleles; genotype and phenotype.\",\"explanation\":\"\",\"worked_example\":\"\",\"activities\":\"\",\"checks\":\"\",\"exit_ticket\":\"\",\"sources\":[]}',NULL,'[2]',0,0,2,NULL,NULL,NULL,'2026-10-19 23:24:16','2026-10-19 23:24:16'),(3,1,2,NULL,'Math','draft','Grade 9',50,NULL,'en',NULL,'### Learning Objectives\n- **Solve linear algebraic equations** in one variable, including equations with fractions and variables on both sides.\n- **Translate word problems** into algebraic expressions and equations.\n- **Check solutions** for correctness by substitution.\n- **Communicate reasoning** clearly using proper mathematical notation.\n\n*These objectives align with the Grade 9 curriculum for algebraic problem solving.*','{\"objectives\":\"### Learning Objectives\\n- **Solve linear algebraic equations** in one variable, including equations with fractions and variables on both sides.\\n- **Translate word problems** into algebraic expressions and equations.\\n- **Check solutions** for correctness by substitution.\\n- **Communicate reasoning** clearly using proper mathematical notation.\\n\\n*These objectives align with the Grade 9 curriculum for algebraic problem solving.*\",\"prior_knowledge\":\"### Prior Knowledge\\n- Basic arithmetic operations (addition, subtraction, multiplication, division).\\n- Understanding of variables and simple expressions (e.g., \\\\(3x + 5\\\\)).\\n- Ability to simplify fractions and work with negative numbers.\\n- Experience solving simple equations such as \\\\(x + 4 = 9\\\\).\",\"explanation\":\"### Teacher Explanation\\n1. **Introduce the structure of a linear equation**: an expression containing a variable raised to the first power set equal to another expression.\\n   \\\\[ ax + b = c \\\\]\\n2. **Isolate the variable** by performing inverse operations on both sides:\\n   - Subtract or add the constant term.\\n   - Divide or multiply by the coefficient of the variable.\\n3. **Emphasize the balance principle** – whatever you do to one side, you must do to the other.\\n4. **Discuss special cases**:\\n   - Variables on both sides (e.g., \\\\(2x + 3 = x - 5\\\\)).\\n   - Equations with fractions (e.g., \\\\(\\\\frac{1}{2}x = 4\\\\)).\\n5. **Model checking the solution** by substituting the found value back into the original equation.\",\"worked_example\":\"### Worked Example\\nSolve \\\\(3x - 7 = 2x + 5\\\\).\\n\\n1. **Subtract \\\\(2x\\\\) from both sides**:\\n   \\\\[3x - 2x - 7 = 5\\\\]\\n   \\\\[x - 7 = 5\\\\]\\n2. **Add 7 to both sides**:\\n   \\\\[x = 12\\\\]\\n3. **Check**:\\n   \\\\[3(12) - 7 = 36 - 7 = 29\\\\]\\n   \\\\[2(12) + 5 = 24 + 5 = 29\\\\]\\n   Both sides equal 29, so \\\\(x = 12\\\\) is correct.\",\"activities\":\"### Classroom Activities\\n- **Guided Practice**: Students work in pairs to solve three teacher‑selected equations, recording each step.\\n- **Think‑Pair‑Share**: Pose a word‑problem; students first think individually, then discuss with a partner, and finally share solutions with the class.\\n- **Equation Relay**: Teams race to correctly simplify and solve a series of equations projected on the board.\",\"checks\":\"### Formative Checks\\n- **Exit Slip**: Each student solves one equation on a sticky note and hands it in before leaving.\\n- **Mini‑Quiz** (5 minutes): 3 short problems—one with a variable on each side, one with fractions, and one word problem.\\n- **Observation**: Teacher circulates, noting students who correctly apply the balance principle and who need prompting.\",\"exit_ticket\":\"### Exit Ticket Prompt\\n*Write down the solution to the equation \\\\(\\\\frac{2}{3}x - 4 = 5\\\\) and briefly explain one step you used to isolate \\\\(x\\\\).*\",\"sources\":[]}',NULL,'[]',1,0,2,NULL,NULL,NULL,'2026-10-22 19:35:46','2026-10-22 19:36:47'),(4,1,2,NULL,'ww','draft','Grade 9',50,NULL,'en',NULL,'- Identify **variables** and **coefficients** in algebraic expressions. [2]\n- Write simple **equations** that state two expressions are equal. [2]\n- Solve one‑step equations using addition/subtraction or division/multiplication. [3]\n- Simplify like terms by combining coefficients. [4]\n- Apply these skills to solve practice problems. [5]','{\"objectives\":\"- Identify **variables** and **coefficients** in algebraic expressions. [2]\\n- Write simple **equations** that state two expressions are equal. [2]\\n- Solve one‑step equations using addition\\/subtraction or division\\/multiplication. [3]\\n- Simplify like terms by combining coefficients. [4]\\n- Apply these skills to solve practice problems. [5]\",\"prior_knowledge\":\"- Basic arithmetic operations (addition, subtraction, multiplication, division).\\n- Understanding that a **letter can represent an unknown number**. [1]\\n- Ability to read and follow step‑by‑step instructions.\",\"explanation\":\"In algebra we use **variables** (letters such as \\\\(x\\\\)) to stand for numbers we don’t yet know. The **coefficient** is the number placed in front of the variable (e.g., the 4 in \\\\(4x\\\\)). An **equation** is a statement that two expressions are equal, like \\\\(x + 3 = 8\\\\). To solve a one‑step equation we perform the opposite operation on both sides to isolate the variable. For example, subtract 3 from both sides of \\\\(x + 3 = 8\\\\) to get \\\\(x = 5\\\\). When terms have the same variable part they are **like terms** and can be combined by adding or subtracting their coefficients. [2][3][4]\",\"worked_example\":\"### Example: Solve \\\\(2x = 14\\\\)\\n1. Identify the operation applied to \\\\(x\\\\) – it is being **multiplied** by 2.\\n2. Perform the inverse operation (division) on both sides:\\n   \\\\[ \\\\frac{2x}{2} = \\\\frac{14}{2} \\\\]\\n3. Simplify:\\n   \\\\[ x = 7 \\\\]\\nThis follows the steps shown in the source example. [3]\",\"activities\":\"- **Teacher‑led discussion** (10 min): Review variables, coefficients, and equations using the definitions from the source.\\n- **Guided practice** (15 min): Work through Example A (\\\\(x+3=8\\\\)) and Example B (\\\\(2x=14\\\\)) together on the board. [3]\\n- **Partner activity** (15 min): Students solve the practice set from source 5:\\n  1. \\\\(x + 6 = 10\\\\)\\n  2. \\\\(3x = 18\\\\)\\n  3. \\\\(2x + 4 = 12\\\\)\\n  4. \\\\(5x + 2x =?\\\\)\\n  They check answers with the answer key. [5]\\n- **Whole‑class review** (5 min): Discuss any misconceptions, especially about like terms. [4]\",\"checks\":\"- **Quick‑fire questions** after the guided practice: \\n  *What is the coefficient in \\\\(4x\\\\)?* (Answer: 4) \\n  *What does the equation \\\\(x + 3 = 8\\\\) tell us?* (Answer: the two sides are equal) \\n- **Exit‑ticket preview**: Ask a student to simplify \\\\(3x + 2x\\\\). Expected answer: \\\\(5x\\\\). [4]\",\"exit_ticket\":\"Solve the following equation and write the value of \\\\(x\\\\):\\n\\n\\\\[ 2x + 4 = 12 \\\\]\\n\\n(Show your work on the back of the paper.)\",\"sources\":[{\"n\":1,\"material_id\":10,\"title\":\"Algebra\",\"where\":\"A Quick Guide to Algebra\"},{\"n\":2,\"material_id\":10,\"title\":\"Algebra\",\"where\":\"1. Know the key parts\"},{\"n\":3,\"material_id\":10,\"title\":\"Algebra\",\"where\":\"2. How to solve equations\"},{\"n\":4,\"material_id\":10,\"title\":\"Algebra\",\"where\":\"3. Simplify like terms\"},{\"n\":5,\"material_id\":10,\"title\":\"Algebra\",\"where\":\"4. Practice\"}]}',NULL,'[10]',1,0,2,NULL,NULL,NULL,'2026-10-23 03:56:59','2026-10-23 03:56:59');
