INSERT INTO `questions` VALUES (1,1,1,'multiple_choice','Where does gas exchange between the air and the blood take place?',1.00,'[{\"key\":\"A\",\"text\":\"Trachea\"},{\"key\":\"B\",\"text\":\"Bronchi\"},{\"key\":\"C\",\"text\":\"Alveoli\"},{\"key\":\"D\",\"text\":\"Larynx\"}]','{\"correct\":\"C\"}','Gases diffuse across the thin walls of the alveoli into and out of the surrounding capillaries.','Gas exchange',1,'Breathing and circulation notes: Gas exchange in the alveoli',0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(2,1,2,'multiple_choice','Which chamber of the heart pumps oxygen-rich blood to the rest of the body?',1.00,'[{\"key\":\"A\",\"text\":\"Right atrium\"},{\"key\":\"B\",\"text\":\"Right ventricle\"},{\"key\":\"C\",\"text\":\"Left atrium\"},{\"key\":\"D\",\"text\":\"Left ventricle\"}]','{\"correct\":\"D\"}','The left ventricle has the thickest wall because it pumps blood around the whole body.','The heart',2,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(3,1,3,'true_false','Veins carry blood away from the heart.',1.00,NULL,'{\"correct\":false}','Arteries carry blood away from the heart; veins carry it back.','Blood vessels',2,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(4,1,4,'multiple_choice','Why do oxygen and carbon dioxide move across the walls of the alveoli so easily?',2.00,'[{\"key\":\"A\",\"text\":\"The walls are thick and muscular\"},{\"key\":\"B\",\"text\":\"The walls are one cell thick and moist\"},{\"key\":\"C\",\"text\":\"The alveoli contain valves\"},{\"key\":\"D\",\"text\":\"The air in the alveoli is under high pressure\"}]','{\"correct\":\"B\"}','Thin, moist walls and a large surface area let the gases diffuse quickly.','Gas exchange',1,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(5,1,5,'true_false','When you inhale, the diaphragm contracts and moves down.',1.00,NULL,'{\"correct\":true}','The contracting diaphragm flattens, making the chest cavity larger so air flows in.','Breathing',3,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(6,1,6,'short_answer','Name the tiny blood vessels where substances pass between the blood and the body\'s cells.',1.00,NULL,'{\"accepted\":[\"capillaries\",\"capillary\"],\"case_sensitive\":false}','Capillaries have walls one cell thick.','Blood vessels',2,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(7,3,1,'multiple_choice','Two heterozygous tall pea plants (Tt) are crossed. What is the probability that an offspring is short?',1.00,'[{\"key\":\"A\",\"text\":\"0\"},{\"key\":\"B\",\"text\":\"1 in 4\"},{\"key\":\"C\",\"text\":\"1 in 2\"},{\"key\":\"D\",\"text\":\"3 in 4\"}]','{\"correct\":\"B\"}','The cross gives TT, Tt, Tt and tt; only tt is short, so 1 in 4.','Punnett squares',5,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(8,3,2,'true_false','A person with type AB blood shows both the A and the B allele because they are codominant.',1.00,NULL,'{\"correct\":true}','In codominance both alleles are fully expressed.','Non-Mendelian inheritance',4,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(9,3,3,'multiple_choice','What do we call the trait that an organism shows?',1.00,'[{\"key\":\"A\",\"text\":\"Genotype\"},{\"key\":\"B\",\"text\":\"Phenotype\"},{\"key\":\"C\",\"text\":\"Allele\"},{\"key\":\"D\",\"text\":\"Gamete\"}]','{\"correct\":\"B\"}','The phenotype is the observable trait; the genotype is the allele combination.','Vocabulary',4,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(10,3,4,'short_answer','What is the term for different versions of the same gene?',1.00,NULL,'{\"accepted\":[\"alleles\",\"allele\"],\"case_sensitive\":false}','Different versions of a gene are alleles.','Vocabulary',4,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(11,3,5,'essay','In three or four sentences, explain how two tall parent plants can have a short offspring.',4.00,NULL,NULL,NULL,'Punnett squares',5,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(12,5,1,'multiple_choice','Where does gas exchange between the air and the blood take place?',1.00,'[{\"key\":\"A\",\"text\":\"Trachea\"},{\"key\":\"B\",\"text\":\"Bronchi\"},{\"key\":\"C\",\"text\":\"Alveoli\"},{\"key\":\"D\",\"text\":\"Larynx\"}]','{\"correct\":\"C\"}','Gases diffuse across the thin walls of the alveoli into and out of the surrounding capillaries.','Gas exchange',1,'Breathing and circulation notes: Gas exchange in the alveoli',0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(13,5,2,'multiple_choice','Which chamber of the heart pumps oxygen-rich blood to the rest of the body?',1.00,'[{\"key\":\"A\",\"text\":\"Right atrium\"},{\"key\":\"B\",\"text\":\"Right ventricle\"},{\"key\":\"C\",\"text\":\"Left atrium\"},{\"key\":\"D\",\"text\":\"Left ventricle\"}]','{\"correct\":\"D\"}','The left ventricle has the thickest wall because it pumps blood around the whole body.','The heart',2,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(14,5,3,'true_false','Veins carry blood away from the heart.',1.00,NULL,'{\"correct\":false}','Arteries carry blood away from the heart; veins carry it back.','Blood vessels',2,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(15,5,4,'multiple_choice','Why do oxygen and carbon dioxide move across the walls of the alveoli so easily?',2.00,'[{\"key\":\"A\",\"text\":\"The walls are thick and muscular\"},{\"key\":\"B\",\"text\":\"The walls are one cell thick and moist\"},{\"key\":\"C\",\"text\":\"The alveoli contain valves\"},{\"key\":\"D\",\"text\":\"The air in the alveoli is under high pressure\"}]','{\"correct\":\"B\"}','Thin, moist walls and a large surface area let the gases diffuse quickly.','Gas exchange',1,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(16,5,5,'true_false','When you inhale, the diaphragm contracts and moves down.',1.00,NULL,'{\"correct\":true}','The contracting diaphragm flattens, making the chest cavity larger so air flows in.','Breathing',3,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(17,5,6,'short_answer','Name the tiny blood vessels where substances pass between the blood and the body\'s cells.',1.00,NULL,'{\"accepted\":[\"capillaries\",\"capillary\"],\"case_sensitive\":false}','Capillaries have walls one cell thick.','Blood vessels',2,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(18,6,1,'multiple_choice','Which equation is quadratic?',1.00,'[{\"key\":\"A\",\"text\":\"3x + 2 = 0\"},{\"key\":\"B\",\"text\":\"x^2 - 4x + 3 = 0\"},{\"key\":\"C\",\"text\":\"x^3 = 8\"},{\"key\":\"D\",\"text\":\"2\\/x = 5\"}]','{\"correct\":\"B\"}','The highest power of x is 2.','Standard form',NULL,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(19,6,2,'multiple_choice','Solve by factoring: x^2 + 5x + 6 = 0',2.00,'[{\"key\":\"A\",\"text\":\"x = 2 or x = 3\"},{\"key\":\"B\",\"text\":\"x = -2 or x = -3\"},{\"key\":\"C\",\"text\":\"x = -1 or x = -6\"},{\"key\":\"D\",\"text\":\"x = 1 or x = 6\"}]','{\"correct\":\"B\"}','(x + 2)(x + 3) = 0, so x = -2 or x = -3.','Factoring',NULL,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(20,6,3,'multiple_choice','Solve by factoring: x^2 - 7x + 10 = 0',2.00,'[{\"key\":\"A\",\"text\":\"x = 2 or x = 5\"},{\"key\":\"B\",\"text\":\"x = -2 or x = -5\"},{\"key\":\"C\",\"text\":\"x = 1 or x = 10\"},{\"key\":\"D\",\"text\":\"x = -1 or x = -10\"}]','{\"correct\":\"A\"}','(x - 2)(x - 5) = 0.','Factoring',NULL,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(21,6,4,'true_false','If (x - 4)(x + 1) = 0, then x = 4 or x = -1.',1.00,NULL,'{\"correct\":true}','Set each factor equal to zero.','Zero product property',NULL,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(22,6,5,'short_answer','What is the positive solution of x^2 - 49 = 0?',1.00,NULL,'{\"accepted\":[\"7\",\"x = 7\",\"x=7\"],\"case_sensitive\":false}','x^2 = 49, so x = 7 or x = -7.','Extracting square roots',NULL,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(23,8,1,'multiple_choice','Which equation is quadratic?',1.00,'[{\"key\":\"A\",\"text\":\"3x + 2 = 0\"},{\"key\":\"B\",\"text\":\"x^2 - 4x + 3 = 0\"},{\"key\":\"C\",\"text\":\"x^3 = 8\"},{\"key\":\"D\",\"text\":\"2\\/x = 5\"}]','{\"correct\":\"B\"}','The highest power of x is 2.','Standard form',NULL,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(24,8,2,'multiple_choice','Solve by factoring: x^2 + 5x + 6 = 0',2.00,'[{\"key\":\"A\",\"text\":\"x = 2 or x = 3\"},{\"key\":\"B\",\"text\":\"x = -2 or x = -3\"},{\"key\":\"C\",\"text\":\"x = -1 or x = -6\"},{\"key\":\"D\",\"text\":\"x = 1 or x = 6\"}]','{\"correct\":\"B\"}','(x + 2)(x + 3) = 0, so x = -2 or x = -3.','Factoring',NULL,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(25,8,3,'multiple_choice','Solve by factoring: x^2 - 7x + 10 = 0',2.00,'[{\"key\":\"A\",\"text\":\"x = 2 or x = 5\"},{\"key\":\"B\",\"text\":\"x = -2 or x = -5\"},{\"key\":\"C\",\"text\":\"x = 1 or x = 10\"},{\"key\":\"D\",\"text\":\"x = -1 or x = -10\"}]','{\"correct\":\"A\"}','(x - 2)(x - 5) = 0.','Factoring',NULL,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(26,8,4,'true_false','If (x - 4)(x + 1) = 0, then x = 4 or x = -1.',1.00,NULL,'{\"correct\":true}','Set each factor equal to zero.','Zero product property',NULL,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(27,8,5,'short_answer','What is the positive solution of x^2 - 49 = 0?',1.00,NULL,'{\"accepted\":[\"7\",\"x = 7\",\"x=7\"],\"case_sensitive\":false}','x^2 = 49, so x = 7 or x = -7.','Extracting square roots',NULL,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(28,11,1,'multiple_choice','Which structure carries air from the larynx to the bronchi?',2.00,'[{\"key\":\"A\",\"text\":\"Trachea\"},{\"key\":\"B\",\"text\":\"Alveoli\"},{\"key\":\"C\",\"text\":\"Diaphragm\"},{\"key\":\"D\",\"text\":\"Capillaries\"}]','{\"correct\":\"A\"}',NULL,'Breathing',3,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(29,11,2,'multiple_choice','Which blood vessels carry blood back to the heart?',2.00,'[{\"key\":\"A\",\"text\":\"Arteries\"},{\"key\":\"B\",\"text\":\"Veins\"},{\"key\":\"C\",\"text\":\"Capillaries\"},{\"key\":\"D\",\"text\":\"Alveoli\"}]','{\"correct\":\"B\"}',NULL,'Blood vessels',2,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(30,11,3,'multiple_choice','What does the right ventricle pump blood to?',2.00,'[{\"key\":\"A\",\"text\":\"The brain\"},{\"key\":\"B\",\"text\":\"The lungs\"},{\"key\":\"C\",\"text\":\"The liver\"},{\"key\":\"D\",\"text\":\"The arms and legs\"}]','{\"correct\":\"B\"}',NULL,'The heart',2,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(31,11,4,'true_false','The diaphragm relaxes and moves up when you exhale.',2.00,NULL,'{\"correct\":true}',NULL,'Breathing',3,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(32,11,5,'true_false','Capillary walls are many cells thick.',2.00,NULL,'{\"correct\":false}',NULL,'Blood vessels',2,NULL,0,1,'2026-10-20 23:24:16','2026-10-20 23:24:16'),(33,11,6,'short_answer','Name the gas that the blood picks up in the alveoli.',2.00,NULL,'{\"accepted\":[\"oxygen\"],\"case_sensitive\":false}',NULL,'Gas exchange',1,NULL,0,1,'2026-10-20 23:24:17','2026-10-20 23:24:17'),(34,11,7,'essay','Explain how the respiratory and circulatory systems work together to deliver oxygen to a muscle cell.',8.00,NULL,NULL,NULL,'Gas exchange',1,NULL,0,1,'2026-10-20 23:24:17','2026-10-20 23:24:17'),(35,13,1,'multiple_choice','What term describes different versions of the same gene?',1.00,'[{\"key\":\"A\",\"text\":\"Chromosome\"},{\"key\":\"B\",\"text\":\"Allele\"},{\"key\":\"C\",\"text\":\"Nucleotide\"},{\"key\":\"D\",\"text\":\"Phenotype\"}]','{\"correct\":\"B\"}','The passage states that different versions of the same gene are called alleles.','Alleles',NULL,'Heredity notes, p. 1',1,0,'2026-10-20 23:39:01','2026-10-20 23:39:01'),(36,13,2,'multiple_choice','In Mendel’s pea plant experiments, what proportion of the F2 generation displayed the short‑stem phenotype?',1.00,'[{\"key\":\"A\",\"text\":\"1\\/2\"},{\"key\":\"B\",\"text\":\"1\\/4\"},{\"key\":\"C\",\"text\":\"3\\/4\"},{\"key\":\"D\",\"text\":\"1\\/8\"}]','{\"correct\":\"B\"}','Mendel observed that about one‑fourth of the F2 plants were short, as noted in the passage.','Mendelian Ratios',NULL,'Heredity notes, p. 2',1,0,'2026-10-20 23:39:01','2026-10-20 23:39:01'),(37,13,3,'multiple_choice','When two heterozygous tall pea plants (Tt) are crossed, what is the expected genotypic ratio of their offspring?',1.00,'[{\"key\":\"A\",\"text\":\"1 TT : 1 Tt : 2 tt\"},{\"key\":\"B\",\"text\":\"1 TT : 2 Tt : 1 tt\"},{\"key\":\"C\",\"text\":\"2 TT : 1 Tt : 1 tt\"},{\"key\":\"D\",\"text\":\"3 TT : 1 tt\"}]','{\"correct\":\"B\"}','A Punnett square for Tt × Tt gives the genotypes TT, Tt, Tt, tt, which corresponds to a 1 : 2 : 1 ratio.','Punnett Squares',NULL,'Heredity notes, p. 3',1,0,'2026-10-20 23:39:01','2026-10-20 23:39:01'),(38,13,4,'true_false','In codominance, both alleles are fully expressed in the phenotype.',1.00,NULL,'{\"correct\":true}','The passage explains that in codominance both alleles are fully expressed, such as in AB blood type.','Inheritance Patterns',NULL,'Heredity notes, p. 4',1,0,'2026-10-20 23:39:01','2026-10-20 23:39:01'),(39,13,5,'short_answer','What is the genotype of a person with type O blood?',1.00,NULL,'{\"accepted\":[\"ii\",\"i i\"],\"case_sensitive\":false}','The passage states that the i allele is recessive and a person with type O blood has the genotype ii.','Blood Type Genetics',NULL,'Heredity notes, p. 4',1,0,'2026-10-20 23:39:01','2026-10-20 23:39:01');
