INSERT INTO `review_items` VALUES (1,1,6,1,'quiz','quiz:1:2',NULL,1,NULL,'choice','{\"prompt\":\"Which chamber of the heart pumps oxygen-rich blood to the rest of the body?\",\"explanation\":\"The left ventricle has the thickest wall because it pumps blood around the whole body.\",\"source\":\"Respiratory and circulatory systems check\",\"kind\":\"choice\",\"choices\":[\"Right atrium\",\"Right ventricle\",\"Left atrium\",\"Left ventricle\"],\"correct\":3}',0,0,0,'2026-10-21',NULL,NULL,'2026-10-20 23:31:54','2026-10-20 23:31:54'),(2,1,6,1,'quiz','quiz:1:6',NULL,1,NULL,'text','{\"prompt\":\"Name the tiny blood vessels where substances pass between the blood and the body\'s cells.\",\"explanation\":\"Capillaries have walls one cell thick.\",\"source\":\"Respiratory and circulatory systems check\",\"kind\":\"text\",\"accepted\":[\"capillaries\",\"capillary\"],\"case_sensitive\":false}',0,0,0,'2026-10-21',NULL,NULL,'2026-10-20 23:31:54','2026-10-20 23:31:54'),(3,1,6,3,'quiz','quiz:6:20',NULL,6,NULL,'choice','{\"prompt\":\"Solve by factoring: x^2 - 7x + 10 = 0\",\"explanation\":\"(x - 2)(x - 5) = 0.\",\"source\":\"Solving quadratic equations by factoring\",\"kind\":\"choice\",\"choices\":[\"x = 2 or x = 5\",\"x = -2 or x = -5\",\"x = 1 or x = 10\",\"x = -1 or x = -10\"],\"correct\":0}',0,0,0,'2026-10-21',NULL,NULL,'2026-10-20 23:31:54','2026-10-20 23:31:54'),(4,1,23,2,'quiz','quiz:5:13',NULL,5,NULL,'choice','{\"prompt\":\"Which chamber of the heart pumps oxygen-rich blood to the rest of the body?\",\"explanation\":\"The left ventricle has the thickest wall because it pumps blood around the whole body.\",\"source\":\"Respiratory and circulatory systems check\",\"kind\":\"choice\",\"choices\":[\"Right atrium\",\"Right ventricle\",\"Left atrium\",\"Left ventricle\"],\"correct\":3}',0,0,0,'2026-10-21',NULL,NULL,'2026-10-20 23:42:45','2026-10-20 23:42:45'),(5,1,23,2,'quiz','quiz:5:15',NULL,5,NULL,'choice','{\"prompt\":\"Why do oxygen and carbon dioxide move across the walls of the alveoli so easily?\",\"explanation\":\"Thin, moist walls and a large surface area let the gases diffuse quickly.\",\"source\":\"Respiratory and circulatory systems check\",\"kind\":\"choice\",\"choices\":[\"The walls are thick and muscular\",\"The walls are one cell thick and moist\",\"The alveoli contain valves\",\"The air in the alveoli is under high pressure\"],\"correct\":1}',0,0,0,'2026-10-21',NULL,NULL,'2026-10-20 23:42:45','2026-10-20 23:42:45'),(6,1,23,2,'quiz','quiz:5:16',NULL,5,NULL,'choice','{\"prompt\":\"When you inhale, the diaphragm contracts and moves down.\",\"explanation\":\"The contracting diaphragm flattens, making the chest cavity larger so air flows in.\",\"source\":\"Respiratory and circulatory systems check\",\"kind\":\"choice\",\"true_false\":true,\"correct\":0}',0,0,0,'2026-10-21',NULL,NULL,'2026-10-20 23:42:45','2026-10-20 23:42:45'),(7,1,23,2,'quiz','quiz:5:17',NULL,5,NULL,'text','{\"prompt\":\"Name the tiny blood vessels where substances pass between the blood and the body\'s cells.\",\"explanation\":\"Capillaries have walls one cell thick.\",\"source\":\"Respiratory and circulatory systems check\",\"kind\":\"text\",\"accepted\":[\"capillaries\",\"capillary\"],\"case_sensitive\":false}',0,0,0,'2026-10-21',NULL,NULL,'2026-10-20 23:42:45','2026-10-20 23:42:45'),(8,1,6,5,'practice','practice:1:1',1,NULL,8,'card','{\"kind\":\"card\",\"prompt\":\"What formula helps create an inference?\",\"back\":\"Text clues + what I know = inference.\",\"source\":\"Making inferences while reading, Clues plus knowledge\"}',0,0,0,'2026-10-23',NULL,NULL,'2026-10-22 19:50:45','2026-10-22 19:50:45'),(9,1,6,5,'practice','practice:1:3',1,NULL,8,'card','{\"kind\":\"card\",\"prompt\":\"What can we infer about Mara in the practice passage?\",\"back\":\"She is worried about being late, even though she lets older women board first.\",\"source\":\"Making inferences while reading, A short practice passage\"}',0,0,0,'2026-10-23',NULL,NULL,'2026-10-22 19:50:45','2026-10-22 19:50:45');
