INSERT INTO `site_feedback` VALUES (1,1,6,'student','confusing','I could not find the correct answers after I submitted the quiz. Are they hidden until later?','/student/assignments/1','fixed','Yes. Your teacher releases the answers after the due date, and they then appear on the same page as your receipt.',1,'2026-10-09 23:24:18','2026-10-08 23:24:18','2026-10-09 23:24:18'),(2,1,8,'student','problem','The class page took a long time to open on mobile data this morning.','/student/classes/3','looking',NULL,NULL,NULL,'2026-10-17 23:24:18','2026-10-17 23:24:18'),(3,1,9,'student','idea','Could the flashcards show a picture from the module?','/student/learning','wont_fix','Not during the pilot, but we have noted it for later.',1,'2026-10-12 23:24:18','2026-10-11 23:24:18','2026-10-12 23:24:18'),(4,1,2,'teacher','idea','It would help to print the score grid as a class record sheet.','/teacher/assignments/11/scores','new',NULL,NULL,NULL,'2026-10-19 23:24:18','2026-10-19 23:24:18'),(5,1,3,'teacher','confusing','I was not sure whether held scores count in the gradebook before I release them.','/teacher/gradebook','new',NULL,NULL,NULL,'2026-10-20 17:24:18','2026-10-20 17:24:18');
